import React, { useEffect, useState, useRef } from 'react';
import axios from 'axios';
import TopBar from '../components/TopBar';
import PasswordModal from '../components/PasswordModal';
import { useApp } from '../context/AppContext';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';
const formatDate = (d) => new Date(d).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

const MediaViewer = ({ src, onClose }) => {
  const isVideo = /\.(mp4|mov|avi|webm)$/i.test(src);
  return (
    <div className="media-viewer-overlay" onClick={onClose}>
      <button className="media-viewer-close" onClick={onClose}>✕</button>
      {isVideo
        ? <video src={`${API}${src}`} controls autoPlay style={{ maxWidth: '100%', maxHeight: '80vh', borderRadius: 8 }} onClick={e => e.stopPropagation()} />
        : <img src={`${API}${src}`} alt="View" className="media-viewer-img" onClick={e => e.stopPropagation()} />
      }
    </div>
  );
};

const TrimesterCell = ({ files, trimKey, plant, onUpdate }) => {
  const fileRef = useRef();
  const [toRemove, setToRemove] = useState([]);

  const handleAdd = async (e) => {
    const newFiles = Array.from(e.target.files);
    if (!newFiles.length) return;
    const fd = new FormData();
    newFiles.forEach(f => fd.append(trimKey, f));
    if (toRemove.length) fd.append(`remove${trimKey.charAt(0).toUpperCase() + trimKey.slice(1)}`, JSON.stringify(toRemove));
    await axios.put(`${API}/api/plants/${plant._id}`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
    onUpdate();
  };

  const handleRemove = async (fp) => {
    const fd = new FormData();
    fd.append(`remove${trimKey.charAt(0).toUpperCase() + trimKey.slice(1)}`, JSON.stringify([fp]));
    await axios.put(`${API}/api/plants/${plant._id}`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
    onUpdate();
  };

  const tFiles = plant[trimKey]?.files || [];

  return (
    <td>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, alignItems: 'center' }}>
        {tFiles.length === 0 && <span className="trim-empty">—</span>}
        {tFiles.slice(0, 2).map((fp, i) => {
          const isVideo = /\.(mp4|mov|avi|webm)$/i.test(fp);
          return (
            <div key={i} style={{ position: 'relative' }}>
              {isVideo
                ? <video src={`${API}${fp}`} className="trim-thumb" muted />
                : <img src={`${API}${fp}`} alt="" className="trim-thumb" />
              }
              <button
                onClick={() => handleRemove(fp)}
                style={{ position: 'absolute', top: -4, right: -4, background: '#e53935', color: '#fff', border: 'none', borderRadius: '50%', width: 16, height: 16, fontSize: 9, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
              >✕</button>
            </div>
          );
        })}
        {tFiles.length > 2 && <span style={{ fontSize: '0.72rem', color: 'var(--text-light)' }}>+{tFiles.length - 2}</span>}
        <button
          onClick={() => fileRef.current.click()}
          style={{ background: 'var(--green-pale)', border: '1.5px dashed var(--green-accent)', borderRadius: 6, padding: '4px 6px', cursor: 'pointer', fontSize: '0.72rem', color: 'var(--green-dark)' }}
        >+</button>
        <input type="file" ref={fileRef} accept="image/*,video/*" multiple style={{ display: 'none' }} onChange={handleAdd} />
      </div>
    </td>
  );
};

const EditModal = ({ plant, onClose, onSaved }) => {
  const [form, setForm] = useState({
    plantName: plant.plantName,
    date: plant.date ? plant.date.split('T')[0] : '',
    report: plant.report || ''
  });
  const [submitting, setSubmitting] = useState(false);

  const handleSave = async () => {
    setSubmitting(true);
    const fd = new FormData();
    fd.append('plantName', form.plantName);
    fd.append('date', form.date);
    fd.append('report', form.report);
    await axios.put(`${API}/api/plants/${plant._id}`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
    setSubmitting(false);
    onSaved();
  };

  return (
    <div className="modal-overlay" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="modal">
        <h2>✏️ Edit Plant</h2>
        <p>Update plant details and trimester photos/videos below.</p>
        <div className="form-group">
          <label className="form-label">Plant Name</label>
          <input type="text" className="form-input" value={form.plantName} onChange={e => setForm({ ...form, plantName: e.target.value })} />
        </div>
        <div className="form-group">
          <label className="form-label">Date</label>
          <input type="date" className="form-input" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} />
        </div>
        <div className="form-group">
          <label className="form-label">Report</label>
          <textarea className="form-textarea" value={form.report} onChange={e => setForm({ ...form, report: e.target.value })} />
        </div>

        {['trimester1', 'trimester2', 'trimester3', 'trimester4'].map((t, i) => (
          <div key={t} style={{ marginBottom: 14 }}>
            <div className="form-label">{['1st', '2nd', '3rd', '4th'][i]} Trimester</div>
            <TrimesterCell files={plant[t]?.files || []} trimKey={t} plant={plant} onUpdate={onSaved} />
          </div>
        ))}

        <div className="btn-row">
          <button className="btn-secondary" onClick={onClose}>Cancel</button>
          <button className="btn-primary" style={{ flex: 1 }} onClick={handleSave} disabled={submitting}>
            {submitting ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </div>
    </div>
  );
};

const HistoryPage = () => {
  const [plants, setPlants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showPwd, setShowPwd] = useState(false);
  const [pendingAction, setPendingAction] = useState(null); // { type: 'edit'|'delete', plant }
  const [editPlant, setEditPlant] = useState(null);
  const [viewMedia, setViewMedia] = useState(null);
  const { showToast } = useApp();

  const load = () => {
    setLoading(true);
    axios.get(`${API}/api/plants`).then(r => setPlants(r.data)).finally(() => setLoading(false));
  };

  useEffect(load, []);

  const handleActionClick = (type, plant) => {
    setPendingAction({ type, plant });
    setShowPwd(true);
  };

  const handlePasswordSuccess = async () => {
    setShowPwd(false);
    if (!pendingAction) return;
    if (pendingAction.type === 'edit') {
      setEditPlant(pendingAction.plant);
    } else if (pendingAction.type === 'delete') {
      await axios.delete(`${API}/api/plants/${pendingAction.plant._id}`);
      showToast('Plant deleted successfully.');
      load();
    }
    setPendingAction(null);
  };

  return (
    <>
      <TopBar showTitle={false} />
      {showPwd && (
        <PasswordModal
          title={pendingAction?.type === 'delete' ? 'Confirm Delete' : 'Edit Access'}
          onSuccess={handlePasswordSuccess}
          onClose={() => { setShowPwd(false); setPendingAction(null); }}
        />
      )}
      {editPlant && (
        <EditModal
          plant={editPlant}
          onClose={() => { setEditPlant(null); }}
          onSaved={() => { load(); setEditPlant(null); showToast('Plant updated!'); }}
        />
      )}
      {viewMedia && <MediaViewer src={viewMedia} onClose={() => setViewMedia(null)} />}

      <div className="page-container">
        <div className="about-hero">
          <h1>🏆 Success History</h1>
          <p>All plant records — track every sapling's journey from seed to tree.</p>
        </div>

        {loading ? (
          <div className="spinner" />
        ) : plants.length === 0 ? (
          <div className="empty-state">
            <div className="empty-state-icon">🌱</div>
            <h3>No plants yet</h3>
            <p>Start by uploading your first plant!</p>
          </div>
        ) : (
          <div className="history-table-wrapper">
            <table className="history-table">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Date</th>
                  <th>Plant Name</th>
                  <th>1st Trim.</th>
                  <th>2nd Trim.</th>
                  <th>3rd Trim.</th>
                  <th>4th Trim.</th>
                  <th>Report</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {plants.map((plant, idx) => (
                  <tr key={plant._id}>
                    <td>{idx + 1}</td>
                    <td style={{ whiteSpace: 'nowrap' }}>{formatDate(plant.date)}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 120 }}>
                        {plant.files?.[0] ? (
                          /\.(mp4|mov|avi|webm)$/i.test(plant.files[0])
                            ? <video src={`${API}${plant.files[0]}`} className="trim-thumb" muted onClick={() => setViewMedia(plant.files[0])} style={{ cursor: 'pointer' }} />
                            : <img src={`${API}${plant.files[0]}`} alt="" className="trim-thumb" onClick={() => setViewMedia(plant.files[0])} style={{ cursor: 'pointer' }} />
                        ) : (
                          <span style={{ fontSize: '1.4rem' }}>🌱</span>
                        )}
                        <span style={{ fontWeight: 600 }}>{plant.plantName}</span>
                      </div>
                    </td>
                    {['trimester1', 'trimester2', 'trimester3', 'trimester4'].map(t => {
                      const files = plant[t]?.files || [];
                      if (files.length === 0) return <td key={t}><span className="trim-empty">—</span></td>;
                      const first = files[0];
                      const isVid = /\.(mp4|mov|avi|webm)$/i.test(first);
                      return (
                        <td key={t}>
                          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                            {isVid
                              ? <video src={`${API}${first}`} className="trim-thumb" muted onClick={() => setViewMedia(first)} style={{ cursor: 'pointer' }} />
                              : <img src={`${API}${first}`} alt="" className="trim-thumb" onClick={() => setViewMedia(first)} style={{ cursor: 'pointer' }} />
                            }
                            {files.length > 1 && <span style={{ fontSize: '0.7rem', color: 'var(--text-light)', alignSelf: 'center' }}>+{files.length - 1}</span>}
                          </div>
                        </td>
                      );
                    })}
                    <td style={{ maxWidth: 150 }}>
                      <div style={{ fontSize: '0.75rem', color: 'var(--text-mid)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 140 }}>
                        {plant.report || '—'}
                      </div>
                    </td>
                    <td>
                      <div style={{ display: 'flex', gap: 4 }}>
                        <button className="action-btn edit" onClick={() => handleActionClick('edit', plant)} title="Edit">✏️</button>
                        <button className="action-btn delete" onClick={() => handleActionClick('delete', plant)} title="Delete">🗑️</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </>
  );
};

export default HistoryPage;
